// Scans public/images and writes src/lib/asset-catalog.generated.ts.
// Runs automatically before `dev` and `build`; commit the generated file.
import { readdirSync, writeFileSync, existsSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const kinds = ["items", "shops", "backgrounds", "covers"];
const allowed = /^[a-z0-9][a-z0-9_-]*\.(svg|png|jpe?g|webp|avif)$/;

const catalog = {};
for (const kind of kinds) {
  const dir = join(root, "public", "images", kind);
  const files = existsSync(dir) ? readdirSync(dir).filter((f) => allowed.test(f)).sort() : [];
  catalog[kind] = files.map((f) => `/images/${kind}/${f}`);
}

const body = `// AUTO-GENERATED by scripts/generate-asset-catalog.mjs – do not edit by hand.
export const ASSET_CATALOG = ${JSON.stringify(catalog, null, 2)} as const satisfies Record<string, readonly string[]>;
`;
writeFileSync(join(root, "src", "lib", "asset-catalog.generated.ts"), body);
console.log(`asset catalog: ${Object.values(catalog).flat().length} files`);
